import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '../ui/dialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/tabs';
import { Card, CardContent } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { Progress } from '../ui/progress';
import { Avatar, AvatarFallback } from '../ui/avatar';
import {
  Calendar,
  Users,
  CheckCircle,
  MessageCircle,
  Target,
  TrendingUp,
  Clock,
  DollarSign,
  Plus,
  Edit,
  LayoutGrid,
  List,
  Activity,
} from 'lucide-react';
import { formatDate, formatCurrency } from '../../utils/formatters';
import { KanbanBoard } from '../kanban/KanbanBoard';
import { TaskDetailModal } from './TaskDetailModal';
import axios from 'axios';
import Swal from 'sweetalert2';

const API = process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000';

export const ProjectDetailModal = ({ isOpen, onClose, projectId, onUpdate }) => {
  const [project, setProject] = useState(null);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState('kanban'); // 'kanban' o 'list'
  const [selectedTask, setSelectedTask] = useState(null);
  const [showTaskModal, setShowTaskModal] = useState(false);

  useEffect(() => {
    if (isOpen && projectId) {
      loadProject();
    }
  }, [isOpen, projectId]);

  const loadProject = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      const response = await axios.get(`${API}/api/projects/${projectId}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setProject(response.data);
    } catch (error) {
      console.error('Error loading project:', error);
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: 'No se pudo cargar el proyecto',
        confirmButtonColor: '#dc2626',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleTaskClick = (task) => {
    setSelectedTask(task);
    setShowTaskModal(true);
  };

  const handleAddTask = async () => {
    const { value: formValues } = await Swal.fire({
      title: 'Nueva Tarea',
      html: `
        <input id="swal-input1" class="swal2-input" placeholder="Título de la tarea">
        <textarea id="swal-input2" class="swal2-textarea" placeholder="Descripción (opcional)"></textarea>
      `,
      focusConfirm: false,
      showCancelButton: true,
      confirmButtonColor: '#16a34a',
      cancelButtonColor: '#6b7280',
      confirmButtonText: 'Crear Tarea',
      cancelButtonText: 'Cancelar',
      preConfirm: () => {
        const title = document.getElementById('swal-input1').value;
        const description = document.getElementById('swal-input2').value;
        
        if (!title) {
          Swal.showValidationMessage('El título es requerido');
          return false;
        }
        
        return { title, description };
      }
    });

    if (formValues) {
      try {
        const token = localStorage.getItem('token');
        const updatedProject = {
          ...project,
          tasks: [
            ...project.tasks,
            {
              _id: Date.now().toString(),
              title: formValues.title,
              description: formValues.description,
              status: 'todo',
              priority: 'medium',
              created_at: new Date().toISOString(),
            },
          ],
        };

        await axios.put(
          `${API}/api/projects/${projectId}`,
          { tasks: updatedProject.tasks },
          { headers: { Authorization: `Bearer ${token}` } }
        );

        setProject(updatedProject);
        
        Swal.fire({
          icon: 'success',
          title: 'Tarea Creada',
          confirmButtonColor: '#16a34a',
          timer: 2000,
        });
        
        if (onUpdate) onUpdate();
      } catch (error) {
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'No se pudo crear la tarea',
          confirmButtonColor: '#dc2626',
        });
      }
    }
  };

  const handleTaskMove = async (taskId, newStatus) => {
    try {
      const updatedTasks = project.tasks.map(task =>
        task._id === taskId ? { ...task, status: newStatus } : task
      );

      const token = localStorage.getItem('token');
      await axios.put(
        `${API}/api/projects/${projectId}`,
        { tasks: updatedTasks },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setProject({ ...project, tasks: updatedTasks });
      
      if (onUpdate) onUpdate();
    } catch (error) {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: 'No se pudo mover la tarea',
        confirmButtonColor: '#dc2626',
      });
    }
  };

  const handleTaskUpdate = async (updatedTask) => {
    try {
      const updatedTasks = project.tasks.map(task =>
        task._id === updatedTask._id ? updatedTask : task
      );

      const token = localStorage.getItem('token');
      await axios.put(
        `${API}/api/projects/${projectId}`,
        { tasks: updatedTasks },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setProject({ ...project, tasks: updatedTasks });
      setShowTaskModal(false);
      
      if (onUpdate) onUpdate();
    } catch (error) {
      throw error;
    }
  };

  const handleTaskDelete = async (taskId) => {
    try {
      const updatedTasks = project.tasks.filter(task => task._id !== taskId);

      const token = localStorage.getItem('token');
      await axios.put(
        `${API}/api/projects/${projectId}`,
        { tasks: updatedTasks },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setProject({ ...project, tasks: updatedTasks });
      
      if (onUpdate) onUpdate();
    } catch (error) {
      throw error;
    }
  };

  if (loading) {
    return (
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="sm:max-w-[95vw] max-h-[90vh]">
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-500"></div>
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  if (!project) return null;

  const completedTasks = project.tasks?.filter(t => t.status === 'completed').length || 0;
  const totalTasks = project.tasks?.length || 0;
  const taskProgress = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;

  return (
    <>
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="sm:max-w-[95vw] max-h-[90vh] overflow-hidden flex flex-col p-0">
          {/* Header */}
          <div className="sticky top-0 z-10 bg-white border-b p-6">
            <DialogTitle className="text-2xl mb-2">{project.project_name}</DialogTitle>
            <div className="flex flex-wrap items-center gap-2">
              <Badge className="bg-blue-100 text-blue-800">
                {project.project_type}
              </Badge>
              <Badge className={`
                ${project.priority === 'urgent' ? 'bg-red-100 text-red-800' :
                  project.priority === 'high' ? 'bg-orange-100 text-orange-800' :
                  project.priority === 'medium' ? 'bg-yellow-100 text-yellow-800' :
                  'bg-gray-100 text-gray-800'}
              `}>
                Prioridad: {project.priority}
              </Badge>
              <Badge className={`
                ${project.status === 'completed' ? 'bg-green-100 text-green-800' :
                  project.status === 'in_progress' ? 'bg-blue-100 text-blue-800' :
                  project.status === 'planning' ? 'bg-yellow-100 text-yellow-800' :
                  'bg-red-100 text-red-800'}
              `}>
                {project.status}
              </Badge>
            </div>
          </div>

          {/* Stats Grid */}
          <div className="px-6 py-4 bg-gray-50 border-b">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <Card>
                <CardContent className="p-4">
                  <div className="flex items-center gap-2">
                    <Calendar className="w-4 h-4 text-gray-500" />
                    <div className="text-xs text-gray-600">Inicio</div>
                  </div>
                  <div className="text-sm font-semibold mt-1">
                    {formatDate(project.start_date)}
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardContent className="p-4">
                  <div className="flex items-center gap-2">
                    <Clock className="w-4 h-4 text-gray-500" />
                    <div className="text-xs text-gray-600">Fin estimado</div>
                  </div>
                  <div className="text-sm font-semibold mt-1">
                    {formatDate(project.estimated_end_date)}
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardContent className="p-4">
                  <div className="flex items-center gap-2">
                    <DollarSign className="w-4 h-4 text-gray-500" />
                    <div className="text-xs text-gray-600">Presupuesto</div>
                  </div>
                  <div className="text-sm font-semibold mt-1">
                    {formatCurrency(project.budget)}
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardContent className="p-4">
                  <div className="flex items-center gap-2">
                    <TrendingUp className="w-4 h-4 text-gray-500" />
                    <div className="text-xs text-gray-600">Tareas</div>
                  </div>
                  <div className="text-sm font-semibold mt-1">
                    {completedTasks}/{totalTasks}
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>

          {/* Progress Bar */}
          <div className="px-6 py-4 border-b">
            <div className="flex justify-between items-center mb-2">
              <span className="text-sm font-medium text-gray-700">Progreso del Proyecto</span>
              <span className="text-sm text-gray-600">{Math.round(taskProgress)}%</span>
            </div>
            <Progress value={taskProgress} className="h-2" />
          </div>

          {/* Content */}
          <div className="flex-1 overflow-y-auto px-6 py-4">
            <Tabs defaultValue="tasks" className="w-full">
              <div className="flex items-center justify-between mb-4">
                <TabsList>
                  <TabsTrigger value="tasks">
                    <LayoutGrid className="w-4 h-4 mr-2" />
                    Tareas
                  </TabsTrigger>
                  <TabsTrigger value="overview">
                    <Activity className="w-4 h-4 mr-2" />
                    Resumen
                  </TabsTrigger>
                  <TabsTrigger value="team">
                    <Users className="w-4 h-4 mr-2" />
                    Equipo
                  </TabsTrigger>
                </TabsList>

                {/* View Toggle */}
                <div className="flex gap-2">
                  <Button
                    variant={viewMode === 'kanban' ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => setViewMode('kanban')}
                  >
                    <LayoutGrid className="w-4 h-4" />
                  </Button>
                  <Button
                    variant={viewMode === 'list' ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => setViewMode('list')}
                  >
                    <List className="w-4 h-4" />
                  </Button>
                  <Button onClick={handleAddTask} className="bg-green-600 hover:bg-green-700">
                    <Plus className="w-4 h-4 mr-2" />
                    Nueva Tarea
                  </Button>
                </div>
              </div>

              {/* Tasks Tab */}
              <TabsContent value="tasks" className="mt-0">
                {viewMode === 'kanban' ? (
                  <KanbanBoard
                    tasks={project.tasks || []}
                    onTaskClick={handleTaskClick}
                    onAddTask={handleAddTask}
                    onTaskMove={handleTaskMove}
                  />
                ) : (
                  <div className="space-y-2">
                    {project.tasks?.map((task) => (
                      <Card 
                        key={task._id} 
                        className="cursor-pointer hover:shadow-md transition-shadow"
                        onClick={() => handleTaskClick(task)}
                      >
                        <CardContent className="p-4">
                          <div className="flex items-center justify-between">
                            <div className="flex-1">
                              <h4 className="font-semibold text-sm">{task.title}</h4>
                              <p className="text-xs text-gray-600 mt-1">{task.description}</p>
                            </div>
                            <div className="flex items-center gap-2">
                              <Badge variant="outline">{task.status}</Badge>
                              <Badge className={
                                task.priority === 'urgent' ? 'bg-red-100 text-red-700' :
                                task.priority === 'high' ? 'bg-orange-100 text-orange-700' :
                                task.priority === 'medium' ? 'bg-blue-100 text-blue-700' :
                                'bg-gray-100 text-gray-700'
                              }>
                                {task.priority}
                              </Badge>
                            </div>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                )}
              </TabsContent>

              {/* Overview Tab */}
              <TabsContent value="overview" className="space-y-4">
                <Card>
                  <CardContent className="p-4">
                    <h3 className="font-semibold mb-2">Descripción</h3>
                    <p className="text-sm text-gray-600">{project.description}</p>
                  </CardContent>
                </Card>

                {project.milestones?.length > 0 && (
                  <Card>
                    <CardContent className="p-4">
                      <div className="flex justify-between items-center mb-4">
                        <h3 className="font-semibold flex items-center gap-2">
                          <Target className="w-4 h-4" />
                          Hitos
                        </h3>
                      </div>
                      <div className="space-y-2">
                        {project.milestones.map((milestone, index) => (
                          <div key={index} className="flex items-center gap-3 p-2 border rounded">
                            <CheckCircle className={`w-5 h-5 ${milestone.completed ? 'text-green-500' : 'text-gray-300'}`} />
                            <div className="flex-1">
                              <p className="text-sm font-medium">{milestone.title}</p>
                              {milestone.due_date && (
                                <p className="text-xs text-gray-500">
                                  Fecha: {formatDate(milestone.due_date)}
                                </p>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    </CardContent>
                  </Card>
                )}
              </TabsContent>

              {/* Team Tab */}
              <TabsContent value="team" className="space-y-4">
                <div className="grid gap-4">
                  {project.assigned_to?.map((member, index) => (
                    <Card key={index}>
                      <CardContent className="p-4">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-3">
                            <Avatar className="h-10 w-10">
                              <AvatarFallback>
                                {member.full_name?.split(' ').map(n => n[0]).join('')}
                              </AvatarFallback>
                            </Avatar>
                            <div>
                              <p className="font-medium text-sm">{member.full_name}</p>
                              <p className="text-xs text-gray-500">{member.email}</p>
                            </div>
                          </div>
                          <Badge variant="outline">
                            {member.role || 'member'}
                          </Badge>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </TabsContent>
            </Tabs>
          </div>
        </DialogContent>
      </Dialog>

      {/* Task Detail Modal */}
      <TaskDetailModal
        isOpen={showTaskModal}
        onClose={() => {
          setShowTaskModal(false);
          setSelectedTask(null);
        }}
        task={selectedTask}
        onUpdate={handleTaskUpdate}
        onDelete={handleTaskDelete}
        teamMembers={project.assigned_to || []}
      />
    </>
  );
};
